-- Lead Desk · add the 67 leads from the Excel sheet dated 20 Oct – 4 Nov 2026 (LD2026-0986 to LD2026-1052)
-- Run once in Supabase → SQL Editor. Safe to run again: rows already loaded are skipped.
--
-- If a number is already used by a lead someone entered in Lead Desk, the Excel row is saved under the
-- next free number and keeps its Excel number in the field "excelRef". If the same property already has a lead
-- in Lead Desk with a requirement date within 7 days, the Excel row is treated as already entered and skipped.
-- The Messages tab lists what happened to each row.

-- Make sure the lead-number counter exists (it is normally created by 01_schema.sql).
create table if not exists public.lead_counter (
  year  int primary key,
  next  int not null
);
alter table public.lead_counter enable row level security;

do $imp$
declare r record; newid text; n int; y int := 2026; added int := 0; renumbered int := 0; skipped int := 0;
begin
  -- move the counter past the Excel numbers first, so new app leads never take an Excel number
  select greatest(1053, coalesce(max(substring(id from 8)::int) + 1, 1))
    into n from public.leads where id ~ ('^LD' || y || '-[0-9]{4}$');
  insert into public.lead_counter(year, next) values (y, n)
    on conflict (year) do update set next = greatest(public.lead_counter.next, excluded.next);

