 Opera V5.","status":"New","assignedTo":"","priority":"","createdAt":"2026-11-04T09:00:00Z","createdBy":null,"imported":true,"stageAt":{"New":"2026-11-04T09:00:00Z"},"verifiedAt":null,"assignedAt":null,"log":[{"t":"2026-11-04T09:00:00Z","by":"Import","a":"Imported from the 2026 Excel sheet (update of 4 Nov 2026)"}]}}]$j$::jsonb) as x(id text, doc jsonb) loop
    -- already loaded by an earlier run?
    if exists (select 1 from public.leads where id = r.id and account_key = r.doc->>'accountKey')
       or exists (select 1 from public.leads where doc->>'excelRef' = r.id) then
      skipped := skipped + 1; continue;
    end if;
    -- already typed into Lead Desk by hand?
    if exists (select 1 from public.leads l
               where l.account_key = r.doc->>'accountKey'
                 and coalesce((l.doc->>'imported')::boolean, false) = false
                 and abs(coalesce(l.doc->>'requirementDate', left(l.doc->>'createdAt',10))::date - (r.doc->>'requirementDate')::date) <= 7) then
      raise notice '% (%) skipped: this property already has a lead from the same week', r.id, r.doc->>'accountName';
      skipped := skipped + 1; continue;
    end if;
    if exists (select 1 from public.leads where id = r.id) then
      loop
        insert into public.lead_counter(year, next) values (y, 2)
          on conflict (year) do update set next = public.lead_counter.next + 1
          returning next - 1 into n;
        newid := 'LD' || y || '-' || lpad(n::text, 4, '0');
        exit when not exists (select 1 from public.leads where id = newid);
      end loop;
      insert into public.leads(id, doc) values (newid,
        r.doc || jsonb_build_object('ref', newid, 'excelRef', r.id,
          'log', (r.doc->'log') || jsonb_build_array(jsonb_build_object('t', r.doc->>'createdAt', 'by', 'Import',
                 'a', 'Excel number ' || r.id || ' was already used in Lead Desk, so this lead was saved as ' || newid))));
      raise notice '% (%) saved as %', r.id, r.doc->>'accountName', newid;
      renumbered := renumbered + 1;
    else
      insert into public.leads(id, doc) values (r.id, r.doc);
      added := added + 1;
    end if;
  end loop;
  raise notice 'Done: % added with their Excel number, % added under a new number, % skipped', added, renumbered, skipped;
end $imp$;
